function cb.relicWorth(hD,iD)
local jD=iD._unique_item_data and iD._unique_item_data._unique_relic_data
if not jD then
return 0
end
local kD=G.Items[iD.item_id]or{}
local lD,mD=M.types(hD.unit_id)
