return 0
end
local nD,oD=0,0
for pD,qD in pairs(jD._core_damage_type_buffs or{})do
if lD[qD.damage_type]then
nD=nD+(tonumber(qD.mul)or 0)+(tonumber(qD.add_upg)or 0)*0.01+(tonumber(qD.pen)or 0)*0.001
oD=oD+(tonumber(qD.crit)or 0)
end
end
nD=nD+oD*0.5
local rD=M.rows(hD.unit_id)
local sD=rD and rD[rD.max]
local tD=(sD and tonumber(sD.cd)or 0)*M.mult(hD,Tkc[1502])
for uD,vD in pairs(jD._unique_relic_effects or{})do
local wD=type(vD.params)==Tkc[1368]and vD.params or{}
if vD.id==Tkc[1831]then
local xD=math.min(1,(tonumber(wD.extra_damage)or 0)*tD/math.max(1,tonumber(wD.time_interval)or 40))
local yD=M.DRONES and M.DRONES[hD.unit_id]
if yD and yD.late and tD>0 then
local zD=1/tD
xD=xD*zD/(zD+(tonumber(yD.max)or 0)*(tonumber(yD.late.dmg)or 0)*(tonumber(yD.hits)or 1)/math.max(0.1,tonumber(yD.late.cd)or 4))
end
nD=nD+xD
elseif vD.id==Tkc[1832]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.25
elseif vD.id==Tkc[1833]then
nD=nD+(tonumber(wD.dmg_buff)or 0)*oD
elseif vD.id==Tkc[1834]then
if lD.magic then
nD=0
else
nD=nD+(tonumber(wD.dmg_buff)or 0)*0.3
end
elseif vD.id==Tkc[1835]then
if lD.water_damage then
nD=nD+0.05
end
end
end
return nD
end
