local y1=(w1 .cd>0 and w1 .damage/w1 .cd or 0)
local z1=(x1 .cd>0 and x1 .damage/x1 .cd or 0)*M.aoe(x1 .atk,x1 .range)/math.max(0.3,M.aoe(w1 .atk,w1 .range))
local A1=y1>0 and q1*(z1/y1-1)or(v1 or 0)
local B1=r1[s1+2]
if B1 and s1+1<r1 .max and B1 .cd>0 and x1 .cd>0 and y1>0 then
local C1=q1*((B1 .damage/B1 .cd)/y1-1)
local D1=t1+B1 .cost*u1
if C1/D1>A1/t1 then
A1=A1+(C1/D1*t1-A1)*0.5
end
end
local E1=(x1 .range or 0)>(w1 .range or 0)and(1+((x1 .range-w1 .range)/math.max(1,w1 .range)))or 1
return math.max(0,A1)*E1
end
function U.dpsFor(F1,G1)
