table.sort(H1,function(K1,L1)
return K1 .gain/K1 .cost>L1 .gain/L1 .cost
end)
local M1,N1=0,0
for O1,P1 in ipairs(H1)do
if G1<=0 then
break
end
N1=P1 .gain/P1 .cost
local Q1=math.min(1,G1/P1 .cost)
M1=M1+P1 .gain*Q1
G1=G1-P1 .cost*Q1
end
return M1+math.max(0,G1)*N1*0.7
end
function U.shieldDps(R1,S1,T1,U1,V1,W1,X1)
