for Bpb,Cpb in ipairs(tpb)do
local Dpb=rpb[Cpb]
table.insert(Apb,Cpb..Tkc[2256]..(type(Dpb)==Tkc[1368]and L.json(L.plain(Dpb)):sub(1,500)or tostring(Dpb)))
